overview=dict(status='usable',formation=dict(explanation='A leader assigns its term and next index to admitted proposals and sends append requests. Followers match predecessor term/index, preserve committed entries, replace conflicting uncommitted suffixes and report append support after caller persistence. Leader dispatch admits term-qualified tracked responses, updates Match, aggregates only current voters (both majorities when joint), and advances commit only when the selected index has the current leader term. Append-response advancement releases postponed reads and broadcasts decisions; configuration-driven advancement separately broadcasts without that release call. Heartbeats carry a commit capped by peer Match. Followers propagate commit into Ready application delivery, whose external completion is caller-owned.',behavior_ids=['b-replication','b-follower-log','b-configuration','b-persistence','b-application'],fact_ids=['f-commit','f-membership'],source_ids=['s-ack-consumption','s-joint','s-majority','s-log-qualification','s-log-init-append','s-config-switch','s-propagation','src-send-durability']),context=dict(explanation='Election starts only for a promotable voter without unapplied committed configuration changes or pending snapshot. Vote grants require permitted prior-vote state and an up-to-date candidate log; current voter majorities aggregate votes, with self vote deferred to persistence. Pre-vote preserves term/vote and successful pre-vote starts the real campaign. Winning election resets progress, installs leader role and appends a current-term empty entry. Higher terms usually force follower role, with explicit pre-vote and lease exceptions. Reset clears old vote/progress/readOnly support and transfer state but retains committed log and pre-gate pending reads. Lower-term replies are rejected before role consumption; old storage append completion cannot trim entries but committed snapshot completion remains valid. Quorum loss can remove leadership, and transfer catches up a voter then asks it to campaign, abandoning unfinished transfer on timeout.',behavior_ids=['b-epoch','b-election','b-recovery','b-persistence','b-read'],fact_ids=['f-commit','f-membership','f-read-pending'],source_ids=['src-term-dispatch','src-role-transition','src-append-reset','s-election','s-transfer-candidate','s-timers','s-tracker','s-read-release']),connection=dict(explanation='Authority is acquired with votes qualified by log history and local applied membership. Within that authority, durable append replies become eligible Match support for commit. Membership application changes which support is counted; outgoing voters remain required until joint exit, and learners do not count. Old volatile tallies are reset on authority transition, while committed history and term-independent application survive. Storage completions have separate generation checks before unstable history is discarded. Recovery reconstructs term/vote, committed history and configuration from caller storage rather than old volatile tallies. Read-index consumes both a current-term commitment gate and renewed quorum authority (except singleton/lease variants), with request identity and final read execution left to the caller. Node serialization and Ready ordering connect these mechanisms without making emitted work equivalent to completed external work.',behavior_ids=['b-election','b-replication','b-configuration','b-persistence','b-recovery','b-read','b-api','b-application'],fact_ids=['f-commit','f-membership','f-read-pending'],source_ids=['s-node-loop','s-init','s-load-state','s-confchange','s-joint','s-read-release','s-read-contract','src-storage-responses','src-async-contract']),core_gaps=[],open_details=['README same-batch persistence exception conflicts with Ready interface; legality of that overlap remains unresolved.','Reachability and responsibility of postponed reads when configuration switch commits without release remain open; ReadIndex explicitly allows loss/retry.','AutoLeave retry after aborted transfer and no further application remains unexplained.','Detailed rejection-hint optimization, configuration validation override and mixed-version read retry semantics are not fully investigated.'],rationale='Representative formation and authority paths, their persistence/configuration/recovery support, old-message handling and application boundary have been traced. Remaining local questions are retained without treating this map as exhaustive coverage or evidence of correctness.')
surfaces=[dict(entry_point='README.md:118 versus node.go:74-101',disposition='UNCLASSIFIED_PROTOCOL_RESPONSIBILITY',reason='Conflicting same-Ready persistence/send ordering statements. Example saves entries before sending, but does not resolve the weaker README permission.',source_ids=['src-readme-ready','src-ready-contract','s-example'],high_consequence=True),dict(entry_point='raft.switchToConfig -> maybeCommit',disposition='mapped',behavior_ids=['b-configuration','b-read'],reason='Commit advancement here does not schedule postponed-read release; legal coexistence and applicable completion duty remain open.',source_ids=['s-config-switch','s-read-release','s-read-contract']),dict(entry_point='raft.appliedTo AutoLeave / tickHeartbeat transfer abort',disposition='deferred',reason='AutoLeave proposal may be dropped during transfer; timeout aborts transfer without an explicit auto-leave retry. Need producer history and bounded completion contract.',source_ids=['src-append-reset','s-timers'],high_consequence=False),dict(entry_point='Node.run removal and proposal channel',disposition='deferred',reason='Proposal channel is disabled on local removal but recalculated on leader changes; eligibility and intended forwarding after removal need further contract work.',source_ids=['s-node-loop']),dict(entry_point='Caller disk, network and state machine',disposition='externalized',reason='Library emits Ready/local storage work and requires caller persistence, transport, correlation and application; MemoryStorage and in-repository adapters remain in scope.',source_ids=['src-readme-ready','src-async-contract','s-node-contract','s-storage'])]
mp=dict(version=1,target_profile=dict(system_boundary='Captured go.etcd.io/raft/v3 library including raft state machine, Node/RawNode adapters, membership/quorum, log and MemoryStorage; external caller provides real persistence, network and application.',protocol_contexts=['Node identity, current term/role, local applied simple or joint voter configuration, log entry term/index, read request context.'],external_interfaces=['Node','RawNode','Storage','Ready','MsgStorageAppend/Apply'],ownership=['Node loop serializes raft; RawNode callers serialize externally.','Caller owns durability, message delivery, ordered application and client retries.'],variants=['PreVote','CheckQuorum','ReadOnlySafe/LeaseBased','AsyncStorageWrites','joint configuration','StepDownOnRemoval'],source_ids=['s-node-loop','src-ready-build','src-async-contract','s-storage','s-config-switch']),activities=activities,behaviors=B,facts=F,surfaces=surfaces,core_overview=overview)
